use harbor.signal;

fn render(signal: harbor.signal.Signal) -> String {
    match signal {
        Calm => "calm",
        Gale(wind) => "gale:".concat(other: wind.to_text()),
        Fog(word) => "fog:".concat(other: word),
    }
}

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var parts: List<String> = [];
    var i = 0;
    while i < signals.len() {
        let next = match signals.get(index: i) {
            Some(s) => s,
            None => harbor.signal.Signal.Calm,
        };
        parts.push(item: render(signal: next));
        i = i + 1;
    }
    parts.join(sep: ";")
}

use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.arrive("ax");
    ax = depot.locker.stow(locker: ax, load: 12);
    ax = depot.locker.stow(locker: ax, load: 9);

    var bay = depot.locker.arrive("bay");
    bay = depot.locker.stow(locker: bay, load: 30);
    bay = depot.locker.stow(locker: bay, load: 25);

    var cod = depot.locker.arrive("cod");
    cod = depot.locker.stow(locker: cod, load: 5);

    let labels = [depot.locker.tag(ax), depot.locker.tag(bay), depot.locker.tag(cod)];
    labels.join(",")
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < ponies.len() {
        match ponies.get(index: i) {
            Some(p) => {
                let fed = stable.herd.feed(pony: p, scoops: 3);
                entries.push(item: stable.ledger.entry(pony: fed));
            },
            None => unit,
        };
        i = i + 1;
    }
    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}

