use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let decoded = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + decoded;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

